"""Invoices, built when a departure is recorded (ADR-0009)."""

from __future__ import annotations

from dataclasses import dataclass

from quayline.billing.money import Pence, round_half_up
from quayline.billing.rates import nightly_rate_pence
from quayline.config import settings


@dataclass(frozen=True)
class Invoice:
    stay_id: int
    net: Pence
    vat: Pence

    @property
    def total(self) -> Pence:
        return Pence(self.net + self.vat)


def build_invoice(stay) -> Invoice:
    """Sum the nights, then VAT on its own line (REQ-P2)."""
    length, rate = stay.vessel.length_m, stay.marina.summer_pence_per_m
    net = sum(nightly_rate_pence(night, length, rate) for night in stay.nights)
    vat = round_half_up(net * settings.billing.vat_rate)
    return Invoice(stay_id=stay.id, net=Pence(net), vat=Pence(vat))


def on_departure_recorded(stay, jobs) -> None:
    """Enqueue the invoice job; the worker emails it within the hour (REQ-P3)."""
    jobs.enqueue("billing.send_invoice", stay_id=stay.id)

"""Integer pence (ADR-0008)."""

from __future__ import annotations

from decimal import ROUND_HALF_UP, Decimal


class Pence(int):
    """An amount in pence; never a float."""


def round_half_up(value: float) -> int:
    return int(Decimal(str(value)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def format_gbp(amount: Pence) -> str:
    """Pounds and pence for display, from integer pence without a float."""
    pounds, pence = divmod(int(amount), 100)
    return f"£{pounds:,}.{pence:02d}"

"""Choose a berth for a vessel (ADR-0005)."""

from __future__ import annotations

from dataclasses import dataclass

LENGTH_MARGIN_M = 1.0
BEAM_MARGIN_M = 0.4


@dataclass(frozen=True)
class Berth:
    code: str
    length_m: float
    width_m: float
    depth_m: float
    drying: bool = False


@dataclass(frozen=True)
class Vessel:
    name: str
    length_m: float
    beam_m: float
    draft_m: float
    can_dry: bool = False


def fits(berth: Berth, vessel: Vessel, low_water_m: float, clearance_m: float) -> bool:
    """Whether the vessel fits the berth at the lowest low water of the stay (REQ-S1)."""
    if berth.length_m < vessel.length_m + LENGTH_MARGIN_M:
        return False
    if berth.width_m < vessel.beam_m + BEAM_MARGIN_M:
        return False
    if berth.drying:
        return vessel.can_dry
    return berth.depth_m + low_water_m >= vessel.draft_m + clearance_m


def allocate_berth(
    free: list[Berth], vessel: Vessel, low_water_m: float, clearance_m: float
) -> Berth | None:
    """The smallest free berth that fits, ties broken by berth code; None when none fits."""
    candidates = [b for b in free if fits(b, vessel, low_water_m, clearance_m)]
    return min(candidates, key=lambda b: (b.length_m, b.code), default=None)

"""The visitor waitlist (ADR-0007)."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from datetime import datetime


@dataclass(frozen=True)
class Entry:
    vessel_name: str
    requested_at: datetime
    refuge: bool = False


def queue_order(entries: list[Entry]) -> list[Entry]:
    """Refuge requests first, then everyone else by the time they asked."""
    return sorted(entries, key=lambda e: (not e.refuge, e.requested_at))


def next_offer(entries: list[Entry], vessel_fits: Callable[[Entry], bool]) -> Entry | None:
    """The first entry in queue order whose vessel fits the freed berth."""
    return next((e for e in queue_order(entries) if vessel_fits(e)), None)

"""Which channels a message goes by (ADR-0010)."""

from __future__ import annotations

SAFETY_KINDS = frozenset({"storm_warning", "tide_warning"})


def channels_for(kind: str, *, has_email: bool, has_app: bool) -> list[str]:
    """SMS for safety alerts only; email and push for everything else, else the desk."""
    if kind in SAFETY_KINDS:
        return ["sms"]
    channels = []
    if has_email:
        channels.append("email")
    if has_app:
        channels.append("push")
    return channels or ["desk"]

"""The tide-prediction cache (ADR-0003, REQ-S2)."""

from __future__ import annotations

from datetime import UTC, date, datetime, timedelta

from quayline.config import settings


class StaleTides(Exception):
    """The newest prediction is too old; no tidal berth may be offered."""


def parse_feed_time(text: str) -> datetime:
    """A feed timestamp, with or without seconds, as UTC (whatever the feed's label says)."""
    fmt = "%Y-%m-%dT%H:%M:%S" if text.count(":") == 2 else "%Y-%m-%dT%H:%M"
    return datetime.strptime(text, fmt).replace(tzinfo=UTC)


def ensure_fresh(fetched_at: datetime, now: datetime) -> None:
    if now - fetched_at > timedelta(hours=settings.tides.tide_stale_hours):
        raise StaleTides(f"newest prediction fetched at {fetched_at:%Y-%m-%d %H:%M} UTC")


def lowest_low_water(low_water_by_night: dict[date, float], nights: list[date]) -> float:
    """The lowest predicted low water over the nights of a stay, in metres above chart datum."""
    return min(low_water_by_night[night] for night in nights)
